input.content:
function logNote(text){let li=document.createElement('li');li.textContent=text;ui.log.prepend(li);while(ui.log.children.length>4)ui.log.lastChild.remove()}
let toastTimer;
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1900)}
function openDialog(title,text,button='CONTINUE'){document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogText').textContent=text;document.getElementById('dialogClose').textContent=button;document.getElementById('modal').classList.add('show')}
function closeDialog(){document.getElementById('modal').classList.remove('show');if(gameState==='dead'){player.hp=player.maxHp;player.x=elder.x+T*2;player.y=elder.y;gameState='playing';logNote('Rowan saw you safely back to the grove.');refreshUI()}if(gameState==='won'){gameState='playing'}}
document.getElementById('dialogClose').addEventListener('click',closeDialog);
let gameState='playing',questAccepted=false,win=false;
function refreshUI(){ui.hp.textContent=`${player.hp} / ${player.maxHp}`;ui.hpBar.style.width=`${100*player.hp/player.maxHp}%`;ui.xp.textContent=`${player.xp} / ${player.next}`;ui.xpBar.style.width=`${100*player.xp/player.next}%`;ui.level.textContent=`LV ${String(player.level).padStart(2,'0')}`;ui.gold.textContent=player.gold;ui.potions.textContent=player.potions;ui.potionCount.textContent=`× ${player.potions}`;ui.slain.textContent=player.slain;ui.shards.textContent=`${shards.filter(s=>s.got).length} / 3`;if(player.hp<9)ui.hp.style.color='#f1a08a';else ui.hp.style.color='';}
function gainXP(n){player.xp+=n;while(player.xp>=player.next){player.xp-=player.next;player.level++;player.next=Math.round(player.next*1.35);player.maxHp+=5;player.hp=player.maxHp;toast(`Level up! You are now level ${player.level}.`);logNote(`You reached level ${player.level}. Your heart feels stronger.`)}refreshUI()}
function nearThings(){let near=[];near.push({type:'elder',obj:elder,d:Math.hypot(player.x-elder.x,player.y-elder.y)});for(const s of shards)if(!s.got)near.push({type:'shard',obj:s,d:Math.hypot(player.x-s.x,player.y-s.y)});if(!chest.opened)near.push({type:'chest',obj:chest,d:Math.hypot(player.x-chest.x,player.y-chest.y)});near.push({type:'shrine',obj:{x:54*T,y:19*T},d:Math.hypot(player.x-54*T,player.y-19*T)});near.sort((a,b)=>a.d-b.d);return near[0]}
function interact(){if(gameState!=='playing')return;let n=nearThings();if(!n||n.d>T*2.15){toast('Nothing close enough to interact with.');return}
 if(n.type==='elder'){
  if(!questAccepted){questAccepted=true;openDialog('Elder Rowan','The grove is losing its glow, child. Three moonshards were scattered when the old shrine fell quiet. Find them in the woods, and mind the mosslings—they are frightened, not wicked. The path crosses a stream to the east.');logNote('Rowan asked you to restore the shrine with three moonshards.')}
  else if(shards.every(s=>s.got)){openDialog('A grateful grove','The shrine shines again! See how the little lights return to the leaves? You have done more than you know, Trailkeeper. Take this, and carry the grove with you.');player.gold+=25;gainXP(15);questAccepted=false;ui.questTitle.textContent='A Light to Carry';ui.questDesc.textContent='The Hollow Grove glows once more. Rowan’s blessing will travel with you.';ui.questState.textContent='QUEST COMPLETE';logNote('Quest complete — the Hollow Grove is bright again.');toast('Quest complete! +25 shards');win=true;gameState='won';setTimeout(()=>openDialog('The Hollow Light','With the shrine restored, fireflies drift through the canopy once more. The grove remembers your kindness. Your adventure is only beginning…','THE END'),100)}
  else openDialog('Elder Rowan',shards.filter(s=>!s.got).length===3?'The old shrine waits in the eastern clearing, beyond the stream.':'The moonshards hum softly near the places where the grove is brightest. Look for their glow, and cross the stream at the little wooden bridge.');return
 }
 if(n.type==='shard'){n.obj.got=true;player.gold+=5;gainXP(10);refreshUI();logNote('A moonshard joins your pack, warm as a tiny sunrise.');toast('Moonshard found  ·  +5 shards');return}
 if(n.type==='chest'){chest.opened=true;player.gold+=18;player.potions++;gainXP(8);refreshUI();logNote('Found 18 shards and a healing tonic in an old chest.');toast('Treasure!  +18 shards  ·  +1 tonic');return}
 if(n.type==='shrine'){let count=shards.filter(s=>s.got).length;if(count===3){openDialog('The old shrine','The three moonshards lift from your pack and settle into the stone. A soft green-gold light spills across the clearing. Return to Elder Rowan.');questAccepted=true;ui.questDesc.textContent='The shrine is awake. Return to Elder Rowan and share the good news.';logNote('The shrine is restored. Rowan is waiting back along the path.');shards.forEach(s=>s.got=true);refreshUI()}else{toast(`The shrine is quiet. ${3-count} moonshard${3-count===1?'':'s'} still missing.`)} }
}
function attack(){if(gameState!=='playing'||player.attack>0)return;player.attack=.25;let fx=player.x,fy=player.y;if(player.face==='up')fy-=T;if(player.face==='down')fy+=T;if(player.face==='left')fx-=T;if(player.face==='right')fx+=T;let hit=false;for(const e of enemies){if(!e.alive)continue;let d=Math.hypot(player.x-e.x,player.y-e.y),front=Math.hypot(fx-e.x,fy-e.y);if(d<T*1.35||front<T*1.4){e.hp-=7+Math.floor(Math.random()*5);e.hit=.18;hit=true;if(e.hp<=0){e.alive=false;player.slain++;player.gold+=3;gainXP(12);refreshUI();logNote('A mossling dissolved into a few harmless motes.');toast('Mossling soothed  ·  +3 shards')}else toast('A clean hit!')}}if(!hit)toast('Your blade parts the fern fronds.')}
function usePotion(){if(gameState!=='playing')return;if(player.potions<1){toast('No healing tonics left.');return}if(player.hp===player.maxHp){toast('You are already at full vitality.');return}player.potions--;player.hp=Math.min(player.maxHp,player.hp+15);refreshUI();toast('A little warmth returns.  +15 vitality');logNote('You used a healing tonic.')}
function blocked(x,y){let r=7;if(x<8||y<8||x>worldW-8||y>worldH-8)return true;let tx=x/T,ty=y/T;if(isWater(tx,ty))return true;for(const t of trees){if(Math.abs(t.x-x)>t.s+10||Math.abs(t.y-y)>t.s+10)continue;if(Math.hypot(x-(t.x+t.s*.4),y-(t.y+t.s*.78))<r+4)return true}return false}
const keys={},touch={};
function setKey(e,down){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=down;if(down&&!e.repeat){if(k==='e'||k===' ')interact();if(k==='j'||k==='z')attack();if(k==='h')usePotion()}}
window.addEventListener('keydown',e=>setKey(e,true));window.addEventListener('keyup',e=>setKey(e,false));
function buttonAction(id,fn){document.getElementById(id).addEventListener('click',fn)}buttonAction('interactBtn',interact);buttonAction('potionBtn',usePotion);document.getElementById('touchAttack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});
for(const b of document.querySelectorAll('[data-dir]')){const dir=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();touch[dir]=true;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>touch[dir]=false)}
let last=performance.now(),elapsed=0,lastSec=0;
function update(dt){if(gameState!=='playing')return;let dx=0,dy=0;if(keys.w||keys.arrowup||touch.up)dy--;if(keys.s||keys.arrowdown||touch.down)dy++;if(keys.a||keys.arrowleft||touch.left)dx--;if(keys.d||keys.arrowright||touch.right)dx++;if(dx&&dy){dx*=.707;dy*=.707}if(dx||dy){player.walk+=dt*13;if(Math.abs(dx)>Math.abs(dy))player.face=dx<0?'left':'right';else player.face=dy<0?'up':'down';let speed=105+(player.level-1)*3,nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny}
 player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);
 for(const e of enemies){if(!e.alive)continue;e.hit=Math.max(0,e.hit-dt);let d=Math.hypot(player.x-e.x,player.y-e.y);e.phase+=dt*2;if(d<T*5){if(d>T*1.05){let vx=(player.x-e.x)/d,vy=(player.y-e.y)/d,nx=e.x+vx*25*dt,ny=e.y+vy*25*dt;if(!blocked(nx,e.y))e.x=nx;if(!blocked(e.x,ny))e.y=ny}else if(e.hit<=0&&player.invuln<=0){player.hp=Math.max(0,player.hp-4);player.invuln=.8;e.hit=.9;refreshUI();toast('A mossling bumped you!');if(player.hp<=0){gameState='dead';openDialog('Rest here a moment','The grove is gentle with its own. Rowan will help you find your feet again.','RETURN TO ROWAN')}}}else{e.x+=Math.sin(e.phase*.7)*5*dt;e.y+=Math.cos(e.phase*.9)*4*dt}}
}
function render(){let cx=Math.max(0,Math.min(worldW-W,player.x-W/2)),cy=Math.max(0,Math.min(worldH-H,player.y-H/2));ctx.clearRect(0,0,W,H);drawGround(cx,cy);drawWorldObjects(cx,cy);drawPlayer(cx,cy);
 // subtle sun shafts and floating fireflies
 ctx.globalAlpha=.13;ctx.fillStyle='#e7d99a';ctx.beginPath();ctx.moveTo(405-cx*.02,0);ctx.lineTo(460-cx*.02,0);ctx.lineTo(330-cx*.02,H);ctx.lineTo(292-cx*.02,H);ctx.fill();ctx.globalAlpha=1;
 for(let i=0;i<11;i++){let px=(rnd(i,2,81)*W+performance.now()*.006*(i%2?1:-1))%W,py=(rnd(i,7,82)*H+Math.sin(performance.now()/700+i)*9)%H;rect(px,py,2,2,i%3===0?'#d9e8a4':'#c3d89a')}
 let near=nearThings();if(near&&near.d<T*2.15){let txt=near.type==='elder'?'Talk to Elder Rowan':near.type==='shard'?'Gather the moonshard':near.type==='chest'?'Open the old chest':'Examine the shrine';ui.hint.innerHTML=`<kbd>E</kbd> ${txt}`;ui.hint.style.opacity='1'}else{ui.hint.innerHTML='<kbd>WASD</kbd> Wander · <kbd>J</kbd> Swing · <kbd>E</kbd> Interact';ui.hint.style.opacity='.76'}
}
function tick(now){let dt=Math.min(.04,(now-last)/1000);last=now;elapsed+=dt;update(dt);render();if(now-lastSec>1000){lastSec=now;let minute=Math.floor((elapsed*1.15)%60),hour=8+Math.floor((42+elapsed*1.15)/60);ui.clock.textContent=`DAY 01 · ${String(hour%13||1).padStart(2,'0')}:${String(minute).padStart(2,'0')}`};requestAnimationFrame(tick)}
refreshUI();requestAnimationFrame(tick);
})();
</script></body></html>

