(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=canvas.width,H=canvas.height,T=20,MW=72,MH=44,worldW=MW*T,worldH=MH*T;
const ui={hp:document.getElementById('hpText'),hpBar:document.getElementById('hpBar'),xp:document.getElementById('xpText'),xpBar:document.getElementById('xpBar'),level:document.getElementById('level'),gold:document.getElementById('gold'),potions:document.getElementById('potions'),potionCount:document.getElementById('potionCount'),slain:document.getElementById('slain'),shards:document.getElementById('shardCount'),log:document.getElementById('log'),hint:document.getElementById('hint'),toast:document.getElementById('toast'),clock:document.getElementById('clock')};
const player={x:9*T,y:21*T,hp:28,maxHp:28,level:1,xp:0,next:30,gold:12,potions:2,slain:0,face:'down',walk:0,attack:0,invuln:0};const elder={x:12*T,y:21*T};const shards=[{x:20*T,y:12*T,got:false},{x:37*T,y:34*T,got:false},{x:49*T,y:10*T,got:false}];const chest={x:16*T,y:31*T,opened:false};const enemies=[{x:25*T,y:17*T,hp:14,max:14,alive:true,phase:0,hit:0},{x:36*T,y:31*T,hp:16,max:16,alive:true,phase:2,hit:0},{x:47*T,y:16*T,hp:18,max:18,alive:true,phase:1,hit:0},{x:57*T,y:25*T,hp:20,max:20,alive:true,phase:3,hit:0}];
const route=[[5,22],[13,22],[18,20],[23,19],[29,20],[34,23],[40,22],[45,20],[51,19],[58,19],[65,22]];const rnd=(x,y,n=0)=>{let a=Math.sin(x*127.1+y*311.7+n*74.7)*43758.5453;return a-Math.floor(a)};
function routeDist(x,y){let best=999;for(let i=0;i<route.length-1;i++){let [ax,ay]=route[i],[bx,by]=route[i+1],dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((x-ax)*dx+(y-ay)*dy)/(dx*dx+dy*dy)));best=Math.min(best,Math.hypot(x-(ax+t*dx),y-(ay+t*dy)))}return best}
function creekY(x){return 28+Math.sin(x*.17)*1.15+Math.sin(x*.43)*.35}function isWater(x,y){return Math.abs(y-creekY(x))<1.35&&!(x>29&&x<33)}function isPath(x,y){return routeDist(x,y)<1.02}
const trees=[];for(let y=2;y<MH-2;y++)for(let x=2;x<MW-2;x++){if(rnd(x,y,1)>.105)continue;let nearPath=routeDist(x+.5,y+.5)<1.65,water=Math.abs(y+.5-creekY(x+.5))<2.1,clearing=Math.hypot(x+.5-54,y+.5-19)<5.4||Math.hypot(x+.5-12,y+.5-21)<3.2,landmark=shards.some(s=>Math.hypot(x+.5-s.x/T,y+.5-s.y/T)<2.1)||Math.hypot(x+.5-chest.x/T,y+.5-chest.y/T)<2;if(!nearPath&&!water&&!clearing&&!landmark&&rnd(x,y,2)>.12)trees.push({x:x*T+2+rnd(x,y,3)*5,y:y*T+3+rnd(x,y,4)*5,s:15+rnd(x,y,5)*8,hue:rnd(x,y,6)})}
const flowers=[];for(let y=3;y<MH-3;y++)for(let x=3;x<MW-3;x++)if(rnd(x,y,7)>.91&&!isPath(x+.5,y+.5)&&Math.abs(y+.5-creekY(x+.5))>2)flowers.push({x:x*T+4+rnd(x,y,8)*12,y:y*T+5+rnd(x,y,9)*10,c:rnd(x,y,10)>.5?'#e7c980':'#d89cb1'});
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))}
function drawGround(cx,cy){let tx0=Math.floor(cx/T)-1,ty0=Math.floor(cy/T)-1,tx1=tx0+W/T+3,ty1=ty0+H/T+3;for(let ty=ty0;ty<ty1;ty++)for(let tx=tx0;tx<tx1;tx++){if(tx<0||ty<0||tx>=MW||ty>=MH)continue;let sx=tx*T-cx,sy=ty*T-cy,water=isWater(tx+.5,ty+.5),path=isPath(tx+.5,ty+.5);if(water){rect(sx,sy,T,T,'#366d70');rect(sx,sy+3,T,2,'#478b83');if(rnd(tx,ty,12)>.6)rect(sx+4+rnd(tx,ty,13)*10,sy+11,4,1,'#73aba0');continue}if(path){rect(sx,sy,T,T,'#796d4d');if(rnd(tx,ty,14)>.48)rect(sx+3+rnd(tx,ty,15)*12,sy+4+rnd(tx,ty,16)*12,2,2,'#9b8a5e');if(rnd(tx,ty,17)>.87)rect(sx+5,sy+15,7,1,'#5e6249');continue}rect(sx,sy,T,T,(tx+ty)%2?'#456e4e':'#47734f');if(rnd(tx,ty,18)>.57)rect(sx+3+rnd(tx,ty,19)*13,sy+3+rnd(tx,ty,20)*13,2,2,rnd(tx,ty,21)>.5?'#558253':'#3e6748');if(rnd(tx,ty,22)>.91)rect(sx+12,sy+5,2,3,'#8baa62')}
